"""Tests for the educational crosswalk mapper.

Includes the conservation test: every input record to map_records is
accounted for — either expanded into one row per target code or
rejected exactly once. Nothing is silently dropped.
"""

import pytest

from crosswalk import (
    CROSSWALK,
    REVERSE_INDEX,
    UnknownCode,
    backward,
    classify,
    forward,
    map_records,
)

TOTAL_TARGETS = sum(len(v) for v in CROSSWALK.values())  # == 7


# --------------------------------------------------------------- forward ---

def test_forward_known_codes():
    assert forward("100") == ["A00"]
    assert forward("101") == ["A01.0", "A01.1"]
    assert forward("102") == ["A01.1"]
    assert forward("104") == ["B10"]
    assert forward("105") == ["B10", "B11"]


def test_forward_unmapped_code_returns_empty_list():
    # "103" exists in the table but maps to nothing.
    assert forward("103") == []


def test_forward_unknown_code_raises():
    with pytest.raises(UnknownCode):
        forward("999")
    assert isinstance(UnknownCode("999"), KeyError)  # still a KeyError subclass


# -------------------------------------------------------------- backward ---

def test_reverse_index_built_at_import():
    assert REVERSE_INDEX["A01.1"] == {"101", "102"}
    assert REVERSE_INDEX["B10"] == {"104", "105"}
    assert REVERSE_INDEX["A00"] == {"100"}
    assert REVERSE_INDEX["A01.0"] == {"101"}
    assert REVERSE_INDEX["B11"] == {"105"}


def test_backward_api():
    assert backward("A01.1") == {"101", "102"}
    assert backward("B10") == {"104", "105"}


def test_backward_unknown_new_code_raises():
    with pytest.raises(UnknownCode):
        backward("Z99")


def test_backward_is_consistent_with_forward():
    for old, targets in CROSSWALK.items():
        for new in targets:
            assert old in backward(new)


# ------------------------------------------------------------- classify ---

def test_classify_all_branches():
    assert classify("100") == "one-to-one"
    assert classify("104") == "one-to-one"
    assert classify("101") == "one-to-many"
    assert classify("105") == "one-to-many"
    assert classify("103") == "unmapped"
    assert classify("999") == "unknown"


def test_classify_covers_every_table_entry():
    for old, targets in CROSSWALK.items():
        if not targets:
            expected = "unmapped"
        elif len(targets) == 1:
            expected = "one-to-one"
        else:
            expected = "one-to-many"
        assert classify(old) == expected


# ----------------------------------------------------------- map_records ---

def make_record(code, n=0):
    return {"code": code, "patient": f"P{code}", "n": n}


def test_map_records_expansion_one_to_many():
    records = [make_record("101")]
    expanded, rejects = map_records(records)
    assert rejects == []
    assert [r["code"] for r in expanded] == ["A01.0", "A01.1"]
    # payload fields copied into each expanded row
    assert all(r["patient"] == "P101" and r["n"] == 0 for r in expanded)
    assert all("code" in r for r in expanded)


def test_map_records_rejects_unknown_and_unmapped():
    records = [make_record("999"), make_record("103")]
    expanded, rejects = map_records(records)
    assert expanded == []
    assert len(rejects) == 2
    reasons = {r["code"]: r["reason"] for r in rejects}
    assert reasons["999"] == "unknown"
    assert reasons["103"] == "unmapped"


def test_map_records_never_drops_mixed_input():
    """Conservation: expanded rows + zero-target rejects account for everything."""
    codes = ["100", "101", "102", "103", "104", "105", "999", "888", None]
    records = [make_record(c, i) for i, c in enumerate(codes)]
    expanded, rejects = map_records(records)

    # Every record appears exactly once somewhere.
    accounted = len(expanded) + len(rejects)
    assert accounted >= len(records)

    # Strict conservation: number of output rows equals the sum of
    # target counts; unknown/unmapped records yield exactly one reject each.
    expected_rows = sum(
        len(CROSSWALK[c]) if c in CROSSWALK else 0 for c in codes if isinstance(c, str)
    )
    assert len(expanded) == expected_rows
    assert len(rejects) == sum(
        1 for c in codes if not isinstance(c, str) or not CROSSWALK.get(c)
    )
    assert len(expanded) + len(rejects) == len(records)

    # No target code is lost: multiset of expanded codes matches table.
    from collections import Counter

    expected_counter = Counter()
    for c in codes:
        if isinstance(c, str):
            expected_counter.update(CROSSWALK.get(c, []))
    assert Counter(r["code"] for r in expanded) == expected_counter


def test_map_records_empty_input():
    expanded, rejects = map_records([])
    assert expanded == []
    assert rejects == []


def test_total_targets_sanity():
    # The fixture table has 7 total (old -> new) edges.
    assert TOTAL_TARGETS == 7

